CREATE TABLE `ai_model_providers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `provider_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
