INSERT INTO `contests` VALUES (1,'新手入门赛 #1','适合刚开始学习编程的同学，包含基础算法题目。题目难度为简单到普通，涵盖基础数据类型、循环、条件判断等知识点。','PRACTICE','2026-04-14 17:08:15','2026-04-15 17:08:15',120,12,NULL,100,'ENDED','2026-04-21 17:08:15','2026-05-18 17:46:32',0,NULL,1,1,'7F9CA0FE',1),(2,'周赛 第1期 — 算法基础','本周周赛主题为基础算法，包含排序、查找、字符串处理等题目。请在规定时间内完成尽可能多的题目，按总分排名。','RATED','2026-04-24 17:08:15','2026-04-24 19:38:15',150,12,NULL,200,'ENDED','2026-04-21 17:08:15','2026-05-18 17:46:32',0,NULL,1,1,'66A914DE',1),(3,'期中模拟考试','模拟期中考试环境，涵盖数据结构与算法课程前半学期的核心内容，包括链表、栈、队列、二叉树等数据结构题目。','EXAM','2026-05-01 17:08:15','2026-05-01 20:08:15',180,12,NULL,50,'ENDED','2026-04-21 17:08:15','2026-05-18 17:46:32',0,NULL,1,1,'3785E1D5',1),(4,'长期训练赛','长期训练赛','PRACTICE','2026-04-21 16:00:00','2027-04-21 16:00:00',600,1,NULL,NULL,'RUNNING','2026-04-22 23:30:41','2026-05-18 17:46:32',0,NULL,1,1,'A4A21899',1),(5,'每日算法挑战','长期开放的算法练习赛，包含各难度基础题目，适合日常刷题。无排名压力，随时加入随时练习！','PRACTICE','2025-01-01 00:00:00','2099-12-31 23:59:59',0,12,NULL,NULL,'RUNNING','2026-04-22 23:45:57','2026-04-22 23:45:57',0,NULL,1,1,'91B9B03D',1),(6,'入门编程马拉松','面向编程初学者的长期赛事，涵盖数组、字符串、循环等基础题型。完成全部题目即可获得结业证书。','PRACTICE','2025-01-01 00:00:00','2099-12-31 23:59:59',0,12,NULL,NULL,'RUNNING','2026-04-22 23:45:57','2026-04-22 23:45:57',0,NULL,1,1,'150FFE5D',1),(7,'进阶算法挑战赛','中高难度算法题集，涵盖动态规划、图论、贪心等高级算法。适合有一定基础的选手进阶提升。','PRACTICE','2025-03-01 00:00:00','2099-12-31 23:59:59',0,4,NULL,NULL,'RUNNING','2026-04-22 23:45:57','2026-04-22 23:45:57',0,NULL,1,1,'053D6722',1),(8,'2025春季编程能力测试','官方限时编程能力测评，2小时内完成全部题目。成绩将记入排名，前10%获得荣誉证书。','EXAM','2026-04-29 23:45:57','2026-04-29 23:45:57',120,12,NULL,NULL,'ENDED','2026-04-22 23:45:57','2026-05-06 16:58:40',0,NULL,1,1,'8A71626D',1),(9,'数据结构专项训练','系统性训练栈、队列、树、图等数据结构题目，从易到难逐步提升。长期有效，随时参与。','PRACTICE','2025-02-01 00:00:00','2099-12-31 23:59:59',0,4,NULL,NULL,'RUNNING','2026-04-22 23:45:57','2026-04-22 23:45:57',0,NULL,1,1,'4A6603DD',1),(10,'2025元旦算法邀请赛','元旦特别赛事，已结束。可查看排名和题解。','EXAM','2025-01-01 09:00:00','2025-01-01 12:00:00',180,12,NULL,NULL,'ENDED','2025-01-01 00:00:00','2025-01-01 12:00:00',0,NULL,1,1,'3693DD5C',1),(11,'测试','测试','PRACTICE','2026-04-26 16:00:00','2027-04-06 16:00:00',600,1,NULL,NULL,'RUNNING','2026-04-27 16:45:41','2026-05-19 14:49:00',1,'cpp,c,python,java',1,1,'FEB7C87E',1),(12,'第一届兰城杯','干翻蓝桥杯，兰城杯万岁！','PRACTICE','2026-05-17 16:24:47','2099-12-31 15:59:59',0,1,NULL,NULL,'RUNNING','2026-05-18 16:25:22','2026-05-20 05:40:07',0,'cpp,java,c,python,javascript',1,1,'280359B7',1);
