INSERT INTO `learning_paths` VALUES (1,'C语言基础入门','从零开始学习C语言，掌握变量、控制流、函数、指针和内存管理等核心概念，为后续数据结构与算法学习打下坚实基础。','简单','C',NULL,40,100,1,'2026-04-21 14:01:24','2026-04-21 14:01:24',0),(2,'Python编程入门','零基础学习Python 3，从语法基础到面向对象编程，涵盖列表、字典、文件操作等实用技能，适合编程初学者。','简单','Python',NULL,35,90,1,'2026-04-21 14:01:24','2026-04-21 14:01:24',0),(3,'数据结构与算法','系统学习常用数据结构（数组、链表、栈、队列、树、图）和经典算法（排序、搜索、动态规划），提升编程核心竞争力。','普通','通用',NULL,60,80,1,'2026-04-21 14:01:24','2026-04-21 14:01:24',0),(4,'Java面向对象编程','深入学习Java语言特性和面向对象设计，掌握封装、继承、多态、接口、泛型和常用集合框架，为Spring Boot开发做准备。','普通','Java',NULL,50,70,1,'2026-04-21 14:01:24','2026-04-21 14:01:24',0),(5,'算法竞赛入门','面向ACM/ICPC和蓝桥杯等编程竞赛的训练路线，涵盖数论、图论、高级数据结构和常见竞赛技巧，提升算法解题能力。','困难','C++',NULL,80,60,1,'2026-04-21 14:01:24','2026-04-21 14:01:24',0);
