INSERT INTO `problem_sets` VALUES (1,'编程入门基础','适合零基础学习者的入门题集，涵盖基本I/O、简单数学运算和条件判断。','OFFICIAL',1,1,10,'2026-04-22 20:21:03','2026-05-06 23:43:13',0),(2,'数组与排序精选','数组操作与排序算法的经典题目，从基础到进阶。','OFFICIAL',1,1,12,'2026-04-22 20:21:03','2026-04-22 20:21:03',0),(3,'字符串处理专练','字符串操作的经典题目，包括翻转、匹配、编码等。','OFFICIAL',1,1,10,'2026-04-22 20:21:03','2026-04-22 20:21:03',0),(4,'栈与队列应用','栈和队列数据结构的经典应用题目。','OFFICIAL',1,1,8,'2026-04-22 20:21:03','2026-04-22 20:21:03',0),(5,'动态规划入门到进阶','从简单的爬楼梯到背包问题，系统学习动态规划。','OFFICIAL',1,1,12,'2026-04-22 20:21:03','2026-04-22 20:21:03',0),(6,'树与图专题','二叉树遍历、BST验证、图的BFS/DFS、最短路径等经典题目。','OFFICIAL',1,1,10,'2026-04-22 20:21:03','2026-04-22 20:21:03',0),(7,'经典面试算法30题','互联网大厂高频面试算法题精选，覆盖数组、字符串、链表、树、DP等核心考点。','OFFICIAL',1,1,15,'2026-04-22 20:21:03','2026-04-22 20:21:03',0),(8,'GPLT天梯赛模拟','模拟团体程序设计天梯赛题目组合，包含简单(8题)、普通(4题)、困难(3题)的梯度分布。','OFFICIAL',1,1,15,'2026-04-22 20:21:03','2026-04-22 20:21:03',0);
