--
-- Table structure for table `problem_solutions`
--

DROP TABLE IF EXISTS `problem_solutions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `problem_solutions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `problem_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `language` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `code` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_official` tinyint(1) NOT NULL DEFAULT '0',
  `likes` int NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `source_submission_id` bigint DEFAULT NULL COMMENT '题解来源 AC 提交',
  `runtime_ms` int DEFAULT NULL COMMENT '来源提交运行时间 ms',
  `memory_kb` int DEFAULT NULL COMMENT '来源提交内存 KB',
  `reward_granted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已发放题解质量奖励',
  `reward_reason` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '题解奖励原因',
  PRIMARY KEY (`id`),
  KEY `idx_problem_solutions_problem` (`problem_id`),
  KEY `idx_problem_solutions_user` (`user_id`),
  KEY `idx_problem_solutions_language` (`language`),
  KEY `idx_problem_solutions_problem_official` (`problem_id`,`is_official`,`deleted`),
  KEY `idx_problem_solutions_user_created` (`user_id`,`deleted`,`created_at`),
  KEY `idx_problem_solutions_quality` (`problem_id`,`is_official`,`deleted`,`reward_granted`,`runtime_ms`,`memory_kb`),
  KEY `idx_problem_solutions_problem_hot` (`problem_id`,`status`,`deleted`,`is_official`,`likes`,`created_at`),
  CONSTRAINT `fk_problem_solutions_problem` FOREIGN KEY (`problem_id`) REFERENCES `problems` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_problem_solutions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `problem_solutions`
--

LOCK TABLES `problem_solutions` WRITE;
/*!40000 ALTER TABLE `problem_solutions` DISABLE KEYS */;
INSERT INTO `problem_solutions` VALUES (1,86,3,'cpp','题解：两个数组的交集（C++ (GCC 9.2.0)）','## 思路\n\n这里写你的核心思路，比如使用了什么数据结构、为什么这样做。\n\n## 复杂度分析\n\n- 时间复杂度：\n- 空间复杂度：\n\n## 易错点\n\n- \n\n## 关键代码\n\n代码会在下方单独展示，这里可以补充关键逻辑说明。','#include <bits/stdc++.h>\r\nusing namespace std;\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    int n;\r\n    if (!(cin >> n)) return 0;\r\n    set<long long> a;\r\n    for (int i = 0; i < n; ++i) {\r\n        long long x;\r\n        cin >> x;\r\n        a.insert(x);\r\n    }\r\n    int m;\r\n    cin >> m;\r\n    set<long long> ans;\r\n    for (int i = 0; i < m; ++i) {\r\n        long long x;\r\n        cin >> x;\r\n        if (a.count(x)) ans.insert(x);\r\n    }\r\n    if (ans.empty()) {\r\n        cout << \"empty\";\r\n        return 0;\r\n    }\r\n    bool first = true;\r\n    for (long long x : ans) {\r\n        if (!first) cout << \' \';\r\n        first = false;\r\n        cout << x;\r\n    }\r\n    return 0;\r\n}',0,0,1,'2026-05-06 10:47:12','2026-05-06 10:47:12',0,NULL,NULL,NULL,0,NULL),(2,131,1,'java','官方java题解',NULL,'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        for (int i = 0; i < n; i++) {\n            System.out.println(\"Hello, World!\");\n        }\n        sc.close();\n    }\n}',1,0,1,'2026-05-06 12:13:51','2026-05-06 12:13:51',0,NULL,NULL,NULL,0,NULL),(3,131,1,'python','官方python题解',NULL,'n = int(input())\nfor i in range(n):\n    print(\"Hello, World!\")',1,0,1,'2026-05-06 12:13:51','2026-05-06 12:13:51',0,NULL,NULL,NULL,0,NULL),(4,131,1,'cpp','官方cpp题解',NULL,'#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) {\n        cout << \"Hello, World!\" << endl;\n    }\n    return 0;\n}',1,0,1,'2026-05-06 12:13:51','2026-05-06 12:13:51',0,NULL,NULL,NULL,0,NULL),(5,131,1,'python','题解：n次Hello World （Python (3.8.1)）','<p>\n    </p><h2>思路</h2><p>\n    </p><p>先用一两句话说明这道题的关键观察，再写你采用的数据结构或算法。</p><p>\n    </p><h2>复杂度</h2><p>n次循环所以是On\n    </p><p><br></p><p>\n    </p><h2>踩坑点</h2><p>\n    </p><p>没啥</p><p>\n    </p><h2>代码说明</h2><p>\n    </p><p>完整代码会放在下方，你可以在这里解释最关键的几行逻辑。</p><p>\n  </p>','n = int(input())\r\nfor i in range(n):\r\n    print(\"Hello, World!\")',0,0,1,'2026-05-06 12:15:51','2026-05-06 12:15:51',0,NULL,NULL,NULL,0,NULL),(6,125,1,'cpp','题解：单词搜索（C++ (GCC 9.2.0)）','<p>\n    </p><h2>思路</h2><p>\n    </p><p>先用一两句话说明这道题的关键观察，再写你采用的数据结构或算法。</p><p>\n    </p><h2>复杂度</h2><p>\n    </p><p><br></p><p>\n    </p><h2>踩坑点</h2><p>\n    </p><p>比如边界条件、输入输出格式、容易写错的地方。</p><p>\n    </p><h2>代码说明</h2><p>\n    </p><p>完整代码会放在下方，你可以在这里解释最关键的几行逻辑。</p><p>\n  </p>','#include <iostream>\r\n#include <vector>\r\n#include <string>\r\n\r\nusing namespace std;\r\n\r\nclass Solution {\r\nprivate:\r\n    int m, n;\r\n    vector<string> board;\r\n    string word;\r\n    // 方向数组：上、右、下、左\r\n    int dx[4] = {-1, 0, 1, 0};\r\n    int dy[4] = {0, 1, 0, -1};\r\n\r\n    bool dfs(int x, int y, int index) {\r\n        // 如果匹配到最后一个字符\r\n        if (index == word.size()) {\r\n            return true;\r\n        }\r\n\r\n        // 越界或字符不匹配\r\n        if (x < 0 || x >= m || y < 0 || y >= n || board[x][y] != word[index]) {\r\n            return false;\r\n        }\r\n\r\n        // 标记当前单元格为已访问（使用特殊字符）\r\n        char temp = board[x][y];\r\n        board[x][y] = \'#\';\r\n\r\n        // 向四个方向搜索\r\n        for (int i = 0; i < 4; ++i) {\r\n            int nx = x + dx[i];\r\n            int ny = y + dy[i];\r\n            if (dfs(nx, ny, index + 1)) {\r\n                return true; // 找到路径，立即返回\r\n            }\r\n        }\r\n\r\n        // 回溯：恢复单元格\r\n        board[x][y] = temp;\r\n        return false;\r\n    }\r\n\r\npublic:\r\n    bool exist(vector<string>& board, string word) {\r\n        this->board = board;\r\n        this->word = word;\r\n        this->m = board.size();\r\n        this->n = board[0].size();\r\n\r\n        for (int i = 0; i < m; ++i) {\r\n            for (int j = 0; j < n; ++j) {\r\n                // 从每个单元格开始尝试\r\n                if (dfs(i, j, 0)) {\r\n                    return true;\r\n                }\r\n            }\r\n        }\r\n        return false;\r\n    }\r\n};\r\n\r\nint main() {\r\n    int m, n;\r\n    cin >> m >> n;\r\n\r\n    vector<string> board(m);\r\n    for (int i = 0; i < m; ++i) {\r\n        cin >> board[i];\r\n    }\r\n\r\n    string word;\r\n    cin >> word;\r\n\r\n    Solution sol;\r\n    if (sol.exist(board, word)) {\r\n        cout << \"true\" << endl;\r\n    } else {\r\n        cout << \"false\" << endl;\r\n    }\r\n\r\n    return 0;\r\n}',0,0,1,'2026-05-06 16:24:05','2026-05-06 16:24:05',0,NULL,NULL,NULL,0,NULL),(7,132,1,'java','官方java题解',NULL,'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int[][] grid = new int[n][n];\n        for (int i = 0; i < n; ++i)\n            for (int j = 0; j < n; ++j)\n                grid[i][j] = scanner.nextInt();\n\n        int[][] dp = new int[n][n];\n        int[][] val = new int[n][n];\n\n        dp[0][0] = grid[0][0];\n        val[0][0] = grid[0][0];\n\n        for (int i = 0; i < n; ++i) {\n            for (int j = 0; j < n; ++j) {\n                if (i == 0 && j == 0) continue;\n                int maxDp = 0;\n                int maxVal = 0;\n                if (i > 0) {\n                    maxDp = Math.max(maxDp, dp[i-1][j]);\n                    maxVal = Math.max(maxVal, val[i-1][j]);\n                }\n                if (j > 0) {\n                    maxDp = Math.max(maxDp, dp[i][j-1]);\n                    maxVal = Math.max(maxVal, val[i][j-1]);\n                }\n                dp[i][j] = maxDp + grid[i][j];\n                val[i][j] = maxVal + (grid[i][j] == 5 ? grid[i][j] : 0);\n            }\n        }\n\n        System.out.println(dp[n-1][n-1] + val[n-1][n-1]);\n    }\n}',1,0,1,'2026-05-11 18:39:50','2026-05-11 18:39:50',0,NULL,NULL,NULL,0,NULL),(8,132,1,'python','官方python题解',NULL,'import sys\n\nn = int(sys.stdin.readline())\ngrid = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]\n\ndp = [[0]*n for _ in range(n)]\nval = [[0]*n for _ in range(n)]\n\ndp[0][0] = grid[0][0]\nval[0][0] = grid[0][0]\n\nfor i in range(n):\n    for j in range(n):\n        if i == 0 and j == 0:\n            continue\n        maxDp = 0\n        maxVal = 0\n        if i > 0:\n            maxDp = max(maxDp, dp[i-1][j])\n            maxVal = max(maxVal, val[i-1][j])\n        if j > 0:\n            maxDp = max(maxDp, dp[i][j-1])\n            maxVal = max(maxVal, val[i][j-1])\n        dp[i][j] = maxDp + grid[i][j]\n        val[i][j] = maxVal + (grid[i][j] if grid[i][j] == 5 else 0)\n\nprint(dp[n-1][n-1] + val[n-1][n-1])',1,0,1,'2026-05-11 18:39:50','2026-05-11 18:39:50',0,NULL,NULL,NULL,0,NULL),(9,132,1,'cpp','官方cpp题解',NULL,'#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> grid(n, vector<int>(n));\n    for (int i = 0; i < n; ++i)\n        for (int j = 0; j < n; ++j)\n            cin >> grid[i][j];\n\n    vector<vector<int>> dp(n, vector<int>(n, 0));\n    vector<vector<int>> val(n, vector<int>(n, 0));\n\n    dp[0][0] = grid[0][0];\n    val[0][0] = grid[0][0];\n\n    for (int i = 0; i < n; ++i) {\n        for (int j = 0; j < n; ++j) {\n            if (i == 0 && j == 0) continue;\n            int maxDp = 0;\n            int maxVal = 0;\n            if (i > 0) {\n                maxDp = max(maxDp, dp[i-1][j]);\n                maxVal = max(maxVal, val[i-1][j]);\n            }\n            if (j > 0) {\n                maxDp = max(maxDp, dp[i][j-1]);\n                maxVal = max(maxVal, val[i][j-1]);\n            }\n            dp[i][j] = maxDp + grid[i][j];\n            val[i][j] = maxVal + (grid[i][j] * (grid[i][j] == 5 ? 1 : 0));\n        }\n    }\n\n    cout << dp[n-1][n-1] + val[n-1][n-1] << endl;\n    return 0;\n}',1,0,1,'2026-05-11 18:39:50','2026-05-11 18:39:50',0,NULL,NULL,NULL,0,NULL),(10,128,1,'python','高效题解：通配符匹配（Python (3.8.1)）','<p><br></p>','def isMatch(s: str, p: str) -> bool:\r\n    m, n = len(s), len(p)\r\n    dp = [[False] * (n + 1) for _ in range(m + 1)]\r\n    \r\n    # 1. 初始化\r\n    dp[0][0] = True\r\n    \r\n    # 处理 s 为空，p 为 \'*\' 的情况\r\n    for j in range(1, n + 1):\r\n        if p[j-1] == \'*\':\r\n            dp[0][j] = dp[0][j-1]\r\n            \r\n    # 2. 状态转移\r\n    for i in range(1, m + 1):\r\n        for j in range(1, n + 1):\r\n            if p[j-1] == \'?\':\r\n                # FIXED: 必须确保 i > 0，才能匹配单个字符\r\n                dp[i][j] = (i > 0) and dp[i-1][j-1]\r\n            elif p[j-1] == \'*\':\r\n                # \'*\' 匹配空序列 (dp[i][j-1]) 或 匹配多个字符 (dp[i-1][j])\r\n                dp[i][j] = dp[i][j-1] or dp[i-1][j]\r\n            else:\r\n                # 普通字符，必须严格相等\r\n                dp[i][j] = (s[i-1] == p[j-1]) and dp[i-1][j-1]\r\n                \r\n    return dp[m][n]\r\n\r\n# 读取输入（简化版，无需异常处理）\r\ns = input()\r\np = input()\r\nprint(str(isMatch(s, p)).lower())',0,0,1,'2026-05-19 15:42:57','2026-05-19 15:42:57',0,198,30,3412,0,NULL),(11,137,1,'java','官方java题解',NULL,'import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int odd = 0, even = 0;\n        for (int i = 0; i < n; i++) {\n            int x = sc.nextInt();\n            if (x % 2 == 0) even++;\n            else odd++;\n        }\n        System.out.println(odd + \" \" + even);\n    }\n}',1,0,1,'2026-05-19 20:41:04','2026-05-19 20:41:04',0,NULL,NULL,NULL,0,NULL),(12,137,1,'python','官方python题解',NULL,'n = int(input())\nnums = list(map(int, input().split()))\nodd = sum(1 for x in nums if x % 2 != 0)\neven = n - odd\nprint(odd, even)',1,0,1,'2026-05-19 20:41:04','2026-05-19 20:41:04',0,NULL,NULL,NULL,0,NULL),(13,137,1,'cpp','官方cpp题解',NULL,'#include <iostream>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    int odd = 0, even = 0;\n    for (int i = 0; i < n; ++i) {\n        int x;\n        cin >> x;\n        if (x % 2 == 0) even++;\n        else odd++;\n    }\n    cout << odd << \" \" << even << endl;\n    return 0;\n}',1,0,1,'2026-05-19 20:41:04','2026-05-19 20:41:04',0,NULL,NULL,NULL,0,NULL),(14,137,1,'cpp','官方cpp题解',NULL,'#include <iostream>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    int odd = 0, even = 0;\n    for (int i = 0; i < n; ++i) {\n        int x;\n        cin >> x;\n        if (x % 2 == 0) even++;\n        else odd++;\n    }\n    cout << odd << \" \" << even << endl;\n    return 0;\n}',1,0,1,'2026-05-19 20:47:27','2026-05-19 20:47:27',0,NULL,NULL,NULL,0,NULL),(15,137,1,'python','官方python题解',NULL,'n = int(input())\nnums = list(map(int, input().split()))\nodd = sum(1 for x in nums if x % 2 != 0)\neven = n - odd\nprint(odd, even)',1,0,1,'2026-05-19 20:47:27','2026-05-19 20:47:27',0,NULL,NULL,NULL,0,NULL),(16,137,1,'java','官方java题解',NULL,'import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int odd = 0, even = 0;\n        for (int i = 0; i < n; i++) {\n            int x = sc.nextInt();\n            if (x % 2 == 0) even++;\n            else odd++;\n        }\n        System.out.println(odd + \" \" + even);\n    }\n}',1,0,1,'2026-05-19 20:47:27','2026-05-19 20:47:27',0,NULL,NULL,NULL,0,NULL),(17,137,1,'cpp','高效题解：奇偶分离计数（C++ (GCC 9.2.0)）','','#include <iostream>\r\nusing namespace std;\r\n\r\nint main() {\r\n    int n;\r\n    if (cin >> n) { // 读取数字个数\r\n        int odd = 0, even = 0;\r\n        for (int i = 0; i < n; ++i) {\r\n            int x;\r\n            cin >> x; // 读取每一个数\r\n            \r\n            // 判断奇偶性：使用位运算 x & 1 是最稳妥的\r\n            // 结果为 1 是奇数，结果为 0 是偶数\r\n            if ((x & 1) == 1) {\r\n                odd++;\r\n            } else {\r\n                even++;\r\n            }\r\n        }\r\n        \r\n        // 题目要求：先输出奇数，再输出偶数\r\n        cout << odd << \" \" << even << endl;\r\n    }\r\n    return 0;\r\n}',0,0,1,'2026-05-19 20:47:50','2026-05-19 20:47:50',0,219,4,928,0,NULL),(18,71,1,'python','高效题解：统计字符种类数（Python (3.8.1)）','','# 读取输入并去除首尾空白（防止意外换行符）\r\ns = input().strip()\r\n\r\n# 将字符串转为集合，自动去重\r\nunique_set = set(s)\r\n\r\n# 输出集合的大小（即不同字符的数量）\r\nprint(len(unique_set))',0,0,1,'2026-05-19 21:38:49','2026-05-19 21:38:49',0,240,19,3332,0,NULL),(19,138,1,'python','高效题解：整数求和练习（Python (3.8.1)）','','# 读取整数 n\r\nn = int(input())\r\n\r\n# 读取 n 个整数并求和\r\ntotal = 0\r\nfor num in map(int, input().split()):\r\n    total += num\r\n\r\n# 输出结果\r\nprint(total)',0,0,1,'2026-05-20 05:31:28','2026-05-20 05:31:28',0,250,47,3332,0,NULL),(20,102,1,'python','高效题解：对称二叉树判断（Python (3.8.1)）','','import sys\r\n\r\ndef main():\r\n    data = sys.stdin.read().strip().split()\r\n    if not data:\r\n        return\r\n    n = int(data[0])\r\n    arr = list(map(int, data[1:1 + n]))\r\n\r\n    def is_mirror(i, j):\r\n        \"\"\"判断以 i 和 j 为根的两棵子树是否互为镜像\"\"\"\r\n        # 处理索引越界，视为空节点\r\n        val_i = arr[i] if i < n else -1\r\n        val_j = arr[j] if j < n else -1\r\n\r\n        if val_i == -1 and val_j == -1:\r\n            return True\r\n        if val_i == -1 or val_j == -1:\r\n            return False\r\n        if val_i != val_j:\r\n            return False\r\n\r\n        # 递归检查：左子树的左孩子 vs 右子树的右孩子，左子树的右孩子 vs 右子树的左孩子\r\n        left_left = 2 * i + 1\r\n        left_right = 2 * i + 2\r\n        right_left = 2 * j + 1\r\n        right_right = 2 * j + 2\r\n        return is_mirror(left_left, right_right) and is_mirror(left_right, right_left)\r\n\r\n    if n == 0:\r\n        print(\"true\")\r\n    else:\r\n        # 根节点索引为 0，检查其左右子树是否对称\r\n        result = is_mirror(1, 2)\r\n        print(\"true\" if result else \"false\")\r\n\r\nif __name__ == \"__main__\":\r\n    main()',0,0,1,'2026-05-20 05:33:44','2026-05-20 05:33:44',0,251,23,3300,0,NULL),(21,142,1,'python','高效题解：字符串反转输出（Python (3.8.1)）','','# 读取字符串\r\ns = input()\r\n\r\n# 反转字符串并输出\r\nprint(s[::-1])',0,0,1,'2026-05-20 05:34:21','2026-05-20 05:34:21',0,252,31,3332,0,NULL),(22,129,1,'python','高效题解：最大正方形（Python (3.8.1)）','','import sys\r\n\r\ndef main():\r\n    data = sys.stdin.read().strip().split()\r\n    if not data:\r\n        return\r\n    m, n = map(int, data[:2])\r\n    # 剩余部分为矩阵的字符\r\n    chars = data[2:]\r\n    # 构建矩阵\r\n    matrix = [chars[i*n:(i+1)*n] for i in range(m)]\r\n\r\n    dp = [[0] * n for _ in range(m)]\r\n    max_side = 0\r\n\r\n    for i in range(m):\r\n        for j in range(n):\r\n            if matrix[i][j] == \'1\':\r\n                if i == 0 or j == 0:\r\n                    dp[i][j] = 1\r\n                else:\r\n                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1\r\n                max_side = max(max_side, dp[i][j])\r\n\r\n    print(max_side * max_side)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',0,0,1,'2026-05-20 06:17:28','2026-05-20 06:17:28',0,253,40,3332,0,NULL),(23,3,1,'python','高效题解：最大子数组和（Python (3.8.1)）','','import sys\r\n\r\ndef main():\r\n    data = sys.stdin.read().strip().split()\r\n    if not data:\r\n        return\r\n    n = int(data[0])\r\n    nums = list(map(int, data[1:1+n]))\r\n\r\n    # Kadane\'s algorithm\r\n    cur = nums[0]\r\n    best = nums[0]\r\n    for i in range(1, n):\r\n        cur = max(nums[i], cur + nums[i])\r\n        best = max(best, cur)\r\n\r\n    print(best)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',0,0,1,'2026-05-20 06:18:33','2026-05-20 06:18:33',0,254,26,3332,0,NULL),(24,141,1,'cpp','高效题解：偶数个数统计（C++ (GCC 9.2.0)）','','#include <stdio.h>\r\n\r\nint main() {\r\n    int n;\r\n    scanf(\"%d\", &n);\r\n\r\n    int count = 0;\r\n    for (int i = 0; i < n; i++) {\r\n        int x;\r\n        scanf(\"%d\", &x);\r\n        if (x % 2 == 0) {\r\n            count++;\r\n        }\r\n    }\r\n\r\n    printf(\"%d\\n\", count);\r\n    return 0;\r\n}',0,0,1,'2026-05-20 09:31:35','2026-05-20 09:31:35',0,351,4,1512,0,NULL),(25,140,1,'cpp','高效题解：数组最大值统计（C++ (GCC 9.2.0)）','','#include <stdio.h>\r\n\r\nint main() {\r\n    int n;\r\n    scanf(\"%d\", &n);\r\n    \r\n    int max_val, x;\r\n    // 先读第一个数作为初始最大值\r\n    scanf(\"%d\", &max_val);\r\n    \r\n    for (int i = 1; i < n; i++) {\r\n        scanf(\"%d\", &x);\r\n        if (x > max_val) {\r\n            max_val = x;\r\n        }\r\n    }\r\n    \r\n    printf(\"%d\\n\", max_val);\r\n    return 0;\r\n}',0,0,1,'2026-05-20 11:59:37','2026-05-20 11:59:37',0,354,8,932,0,NULL);
