DROP TABLE IF EXISTS `problems`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `problems` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `difficulty` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '普通',
  `input_format` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `output_format` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `input_example` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `output_example` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `examples` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `debug_input_example` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `debug_output_example` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `hint` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `solution` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `time_limit` int NOT NULL DEFAULT '1000',
  `memory_limit` int NOT NULL DEFAULT '262144',
  `visibility` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PRIVATE',
  `author_id` bigint unsigned NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `submit_count` int NOT NULL DEFAULT '0' COMMENT '总提交次数',
  `accept_count` int NOT NULL DEFAULT '0' COMMENT '通过人数(去重)',
  `accept_rate` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '通过率(百分比)',
  PRIMARY KEY (`id`),
  KEY `idx_problems_author` (`author_id`),
  KEY `idx_problems_difficulty` (`difficulty`),
  KEY `idx_problems_visibility` (`visibility`),
  KEY `idx_problems_public_list` (`visibility`,`status`,`deleted`,`id`),
  KEY `idx_problems_public_difficulty` (`visibility`,`status`,`deleted`,`difficulty`,`id`),
  CONSTRAINT `fk_problems_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_problems_difficulty_code` FOREIGN KEY (`difficulty`) REFERENCES `dict_problem_difficulty` (`code`),
  CONSTRAINT `fk_problems_visibility_code` FOREIGN KEY (`visibility`) REFERENCES `dict_problem_visibility` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=147 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

