/*!40000 ALTER TABLE `submission_results` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `submissions`
--

DROP TABLE IF EXISTS `submissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `submissions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `problem_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `code` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `language` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `score` int DEFAULT '0',
  `execution_time` int DEFAULT NULL,
  `memory_used` int DEFAULT NULL,
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `test_results` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `queued_at` datetime DEFAULT NULL COMMENT '评测入队时间',
  `started_at` datetime DEFAULT NULL COMMENT '评测开始时间',
  `finished_at` datetime DEFAULT NULL COMMENT '评测完成时间',
  `judge_node` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行评测的Judge0节点',
  `queue_wait_ms` int DEFAULT NULL COMMENT '入队等待毫秒',
  `judge_duration_ms` int DEFAULT NULL COMMENT '评测执行毫秒',
  `contest_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_submissions_problem_user` (`problem_id`,`user_id`),
  KEY `idx_submissions_user` (`user_id`),
  KEY `idx_submissions_status` (`status`),
  KEY `idx_submissions_user_created` (`user_id`,`created_at`),
  KEY `idx_submissions_problem_status_created` (`problem_id`,`status`,`created_at`),
  KEY `idx_submissions_contest` (`contest_id`),
  KEY `idx_submissions_user_contest_problem_status_time` (`user_id`,`contest_id`,`problem_id`,`status`,`created_at`),
  KEY `idx_submissions_user_problem_contest_time` (`user_id`,`problem_id`,`contest_id`,`created_at`),
  KEY `idx_submissions_status_created_id` (`status`,`created_at`,`id`),
  KEY `idx_submissions_judge_node_finished` (`judge_node`,`finished_at`),
  CONSTRAINT `fk_submissions_contest` FOREIGN KEY (`contest_id`) REFERENCES `contests` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_submissions_problem` FOREIGN KEY (`problem_id`) REFERENCES `problems` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_submissions_status_code` FOREIGN KEY (`status`) REFERENCES `dict_submission_status` (`code`),
  CONSTRAINT `fk_submissions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=376 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `submissions`
--

