, vector<int>(n));\n    vector<vector<int>> transposed(n, vector<int>(m));\n\n    // 输入原矩阵\n    for (int i = 0; i < m; ++i) {\n        for (int j = 0; j < n; ++j) {\n            cin >> matrix[i][j];\n        }\n    }\n\n    // 进行转置操作\n    for (int i = 0; i < m; ++i) {\n        for (int j = 0; j < n; ++j) {\n            transposed[j][i] = matrix[i][j];\n        }\n    }\n\n    // 输出转置后的矩阵\n    for (int i = 0; i < n; ++i) {\n        for (int j = 0; j < m; ++j) {\n            cout << transposed[i][j];\n            // 控制格式，每行最后一个元素后不加空格\n            if (j < m - 1) {\n                cout << \" \";\n            }\n        }\n        cout << endl;\n    }\n\n    return 0;\n}','cpp','ACCEPTED',100,6,948,NULL,NULL,'2026-05-06 11:16:53',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(127,69,3,'#include <iostream>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main() {\r\n    int M, N;\r\n    cin >> M >> N;\r\n    \r\n    // 定义原矩阵\r\n    vector<vector<int>> matrix(M, vector<int>(N));\r\n    \r\n    // 读取矩阵元素\r\n    for (int i = 0; i < M; ++i) {\r\n        for (int j = 0; j < N; ++j) {\r\n            cin >> matrix[i][j];\r\n        }\r\n    }\r\n    \r\n    // 直接输出转置结果\r\n    // 外层循环遍历新矩阵的行（原矩阵的列）\r\n    for (int j = 0; j < N; ++j) {\r\n        // 内层循环遍历新矩阵的列（原矩阵的行）\r\n        for (int i = 0; i < M; ++i) {\r\n            cout << matrix[i][j];\r\n            // 控制输出格式，最后一个元素后不加空格\r\n            if (i != M - 1) {\r\n                cout << \" \";\r\n            }\r\n        }\r\n        cout << endl;\r\n    }\r\n    \r\n    return 0;\r\n}','cpp','ACCEPTED',100,5,956,NULL,NULL,'2026-05-06 11:21:04',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(128,131,1,'n = int(input())\r\nfor i in range(n):\r\n    print(\"Hello, World!\")','python','ACCEPTED',100,45,3296,NULL,NULL,'2026-05-06 12:14:49',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(129,131,1,'n = int(input())\r\nfor i in range(n):\r\n    print(\"Hello, World!\")','python','ACCEPTED',100,25,3244,NULL,NULL,'2026-05-06 12:14:56',NULL,NULL,NULL,NULL