rn true;\r\n        }\r\n\r\n        // 越界或字符不匹配\r\n        if (x < 0 || x >= m || y < 0 || y >= n || board[x][y] != word[index]) {\r\n            return false;\r\n        }\r\n\r\n        // 标记当前单元格为已访问（使用特殊字符）\r\n        char temp = board[x][y];\r\n        board[x][y] = \'#\';\r\n\r\n        // 向四个方向搜索\r\n        for (int i = 0; i < 4; ++i) {\r\n            int nx = x + dx[i];\r\n            int ny = y + dy[i];\r\n            if (dfs(nx, ny, index + 1)) {\r\n                return true; // 找到路径，立即返回\r\n            }\r\n        }\r\n\r\n        // 回溯：恢复单元格\r\n        board[x][y] = temp;\r\n        return false;\r\n    }\r\n\r\npublic:\r\n    bool exist(vector<string>& board, string word) {\r\n        this->board = board;\r\n        this->word = word;\r\n        this->m = board.size();\r\n        this->n = board[0].size();\r\n\r\n        for (int i = 0; i < m; ++i) {\r\n            for (int j = 0; j < n; ++j) {\r\n                // 从每个单元格开始尝试\r\n                if (dfs(i, j, 0)) {\r\n                    return true;\r\n                }\r\n            }\r\n        }\r\n        return false;\r\n    }\r\n};\r\n\r\nint main() {\r\n    int m, n;\r\n    cin >> m >> n;\r\n\r\n    vector<string> board(m);\r\n    for (int i = 0; i < m; ++i) {\r\n        cin >> board[i];\r\n    }\r\n\r\n    string word;\r\n    cin >> word;\r\n\r\n    Solution sol;\r\n    if (sol.exist(board, word)) {\r\n        cout << \"true\" << endl;\r\n    } else {\r\n        cout << \"false\" << endl;\r\n    }\r\n\r\n    return 0;\r\n}','cpp','ACCEPTED',100,10,1076,NULL,NULL,'2026-05-06 16:23:32',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(138,125,1,'#include <iostream>\r\n#include <vector>\r\n#include <string>\r\n\r\nusing namespace std;\r\n\r\nclass Solution {\r\nprivate:\r\n    int m, n;\r\n    vector<string> board;\r\n    string word;\r\n    // 方向数组：上、右、下、左\r\n    int dx[4] = {-1, 0, 1, 0};\r\n    int dy[4] = {0, 1, 0, -1};\r\n\r\n    bool dfs(int x, int y, int index) {\r\n        // 如果匹配到最后一个字符\r\n      