else:\r\n        # 根节点索引为 0，检查其左右子树是否对称\r\n        result = is_mirror(1, 2)\r\n        print(\"true\" if result else \"false\")\r\n\r\nif __name__ == \"__main__\":\r\n    main()','python','ACCEPTED',100,23,3300,NULL,NULL,'2026-05-20 05:33:42',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(252,142,1,'# 读取字符串\r\ns = input()\r\n\r\n# 反转字符串并输出\r\nprint(s[::-1])','python','ACCEPTED',100,31,3332,NULL,NULL,'2026-05-20 05:34:18',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(253,129,1,'import sys\r\n\r\ndef main():\r\n    data = sys.stdin.read().strip().split()\r\n    if not data:\r\n        return\r\n    m, n = map(int, data[:2])\r\n    # 剩余部分为矩阵的字符\r\n    chars = data[2:]\r\n    # 构建矩阵\r\n    matrix = [chars[i*n:(i+1)*n] for i in range(m)]\r\n\r\n    dp = [[0] * n for _ in range(m)]\r\n    max_side = 0\r\n\r\n    for i in range(m):\r\n        for j in range(n):\r\n            if matrix[i][j] == \'1\':\r\n                if i == 0 or j == 0:\r\n                    dp[i][j] = 1\r\n                else:\r\n                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1\r\n                max_side = max(max_side, dp[i][j])\r\n\r\n    print(max_side * max_side)\r\n\r\nif __name__ == \"__main__\":\r\n    main()','python','ACCEPTED',100,40,3332,NULL,NULL,'2026-05-20 06:17:26',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(254,3,1,'import sys\r\n\r\ndef main():\r\n    data = sys.stdin.read().strip().split()\r\n    if not data:\r\n        return\r\n    n = int(data[0])\r\n    nums = list(map(int, data[1:1+n]))\r\n\r\n    # Kadane\'s algorithm\r\n    cur = nums[0]\r\n    best = nums[0]\r\n    for i in range(1, n):\r\n        cur = max(nums[i], cur + nums[i])\r\n        best = max(best, cur)\r\n\r\n    print(best)\r\n\r\nif __name__ == \"__main__\":\r\n    main()','python','ACCEPTED',100,26,3332,NULL,NULL,'2026-05-20 06:18:31',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(255,142,1,'# 读取字符串\r\ns = input()\r\n\r\n# 反转字符串并输出\r\nprint(s[::-1])','python','ACCEPTED',100,21,3464,NULL,NULL,'2026-05-20 08:53:31',NUL