rr[i]);\r\n    }\r\n    \r\n    if (n == 0) return 0;\r\n    \r\n    // 输出第一个元素\r\n    printf(\"%d\", arr[0]);\r\n    \r\n    // 从第二个开始，只输出与前一个不同的元素\r\n    for (int i = 1; i < n; i++) {\r\n        if (arr[i] != arr[i - 1]) {\r\n            printf(\" %d\", arr[i]);\r\n        }\r\n    }\r\n    \r\n    printf(\"\\n\");\r\n    return 0;\r\n}','cpp','ACCEPTED',100,6,932,NULL,NULL,'2026-05-20 12:01:30','2026-05-20 20:01:30','2026-05-20 20:01:30','2026-05-20 20:01:32','JudgeCluster-A',0,1630,12),(357,127,1,'#include <stdio.h>\r\n\r\n#define N 9\r\n\r\n// 检查在 (row, col) 放置 num 是否合法\r\nint isValid(int grid[N][N], int row, int col, int num) {\r\n    // 检查行\r\n    for (int c = 0; c < N; c++) {\r\n        if (grid[row][c] == num) return 0;\r\n    }\r\n    // 检查列\r\n    for (int r = 0; r < N; r++) {\r\n        if (grid[r][col] == num) return 0;\r\n    }\r\n    // 检查 3x3 宫格\r\n    int boxRow = row - row % 3;\r\n    int boxCol = col - col % 3;\r\n    for (int r = 0; r < 3; r++) {\r\n        for (int c = 0; c < 3; c++) {\r\n            if (grid[boxRow + r][boxCol + c] == num) return 0;\r\n        }\r\n    }\r\n    return 1;\r\n}\r\n\r\n// 回溯求解数独\r\nint solveSudoku(int grid[N][N]) {\r\n    for (int row = 0; row < N; row++) {\r\n        for (int col = 0; col < N; col++) {\r\n            if (grid[row][col] == 0) {  // 找到空格\r\n                for (int num = 1; num <= 9; num++) {\r\n                    if (isValid(grid, row, col, num)) {\r\n                        grid[row][col] = num;\r\n                        if (solveSudoku(grid)) return 1;\r\n                        grid[row][col] = 0;  // 回溯\r\n                    }\r\n                }\r\n                return 0;  // 无解\r\n            }\r\n        }\r\n    }\r\n    return 1;  // 全部填满\r\n}\r\n\r\nint main() {\r\n    int grid[N][N];\r\n    \r\n    // 读取输入\r\n    for (int i = 0; i < N; i++) {\r\n        for (int j = 0; j < N; j++) {\r\n            scanf(\"%d\", &grid[i][j]);\r\n        }\r\n    }\r\n    \r\n    // 求解\r\n    solveSudoku(grid);\r\n    \r\n    // 输出结果\r\n    for (int i = 0; i < N; i++) {\r\n        for (int j = 0; j < N; j++) {\r\n            printf(\"%d\", grid[i][j]);\r\n            if (j < N - 1) printf(\" \");\r\n        }\r\n        printf(\"\\n\");\r\n    }\r\n    \r\n    return 0;\r\n}','cpp','ACCEPTED',100,349,1000,NULL,NULL,'2026-05-20 12:02:57','2026-05-20 20:02:57','2026-05-20 20:02:58','2026-05-20 20:02:59','JudgeCluster-A',505,1233,12),(358,129,1,'import sys\r\n\r\ndef main():\r\n    data = sys.stdin.read().strip().split()\r\n    if not data:\r\n        return\r\n    m, n = map(int, data[:2])\r\n    # 剩余部分为矩阵的字符\r\n    chars = data[2:]\r\n    # 构建矩阵\r\n    matrix = [chars[i*n:(i+1)*n] for i in range(m)]\r\n\r\n    dp = [[0] * n for _ in range(m)]\r\n    max_side = 0\r\n\r\n    for i in range(m):\r\n        for j in range(n):\r\n            if matrix[i][j] == \'1\':\r\n                if i == 0 or j == 0:\r\n                    dp[i][j] = 1\r\n                else:\r\n                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1\r\n                max_side = max(max_side, dp[i][j])\r\n\r\n    print(max_side * max_side)\r\n\r\nif __name__ == \"__main__\":\r\n    main()','python','ACCEPTED',100,33,3340,NULL,NULL,'2026-05-20 14:19:18',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(359,98,1,'#include <iostream>\nusing namespace std;\n\nint main() {\n    /* 在此处写入代码 */\n    return 0;\n}','cpp','WRONG_ANSWER',0,8,928,NULL,NULL,'2026-05-20 14:19:30','2026-05-20 22:19:30','2026-05-20 22:19:30','2026-05-20 22:19:35','JudgeCluster-A',60,5209,12),(360,127,1,'#include <stdio.h>\r\n\r\n#define N 9\r\n\r\n// 检查在 (row, col) 放置 num 是否合法\r\nint isValid(int grid[N][N], int row, int col, int num) {\r\n    // 检查行\r\n    for (int c = 0; c < N; c++) {\r\n        if (grid[row][c] == num) return 0;\r\n    }\r\n    // 检查列\r\n    for (int r = 0; r < N; r++) {\r\n        if (grid[r][col] == num) return 0;\r\n    }\r\n    // 检查 3x3 宫格\r\n    int boxRow = row - row % 3;\r\n    int boxCol = 