= 0) prefix[i] = a[i];\r\n        else prefix[i] = prefix[i-1] + a[i];\r\n    }\r\n    while (q--) {\r\n        int l, r;\r\n        cin >> l >> r;\r\n        // 错误：直接使用l,r作为索引，但数组从0开始，应该减1\r\n        // 这里故意不减去1，导致越界或错误\r\n        cout << prefix[r] - prefix[l-1] << endl; // 如果l=1，则prefix[0]未定义？实际上我们定义了prefix[0]，但l-1可能为0，没问题？但索引不对。\r\n    }\r\n    return 0;\r\n}','cpp','WRONG_ANSWER',20,5,940,NULL,NULL,'2026-05-27 16:05:52','2026-05-28 00:05:52','2026-05-28 00:05:52','2026-05-28 00:05:56','JudgeCluster-A',0,3562,12),(371,127,1,'#include <stdio.h>\r\n\r\n#define N 9\r\n\r\n// 检查在 (row, col) 放置 num 是否合法\r\nint isValid(int grid[N][N], int row, int col, int num) {\r\n    // 检查行\r\n    for (int c = 0; c < N; c++) {\r\n        if (grid[row][c] == num) return 0;\r\n    }\r\n    // 检查列\r\n    for (int r = 0; r < N; r++) {\r\n        if (grid[r][col] == num) return 0;\r\n    }\r\n    // 检查 3x3 宫格\r\n    int boxRow = row - row % 3;\r\n    int boxCol = col - col % 3;\r\n    for (int r = 0; r < 3; r++) {\r\n        for (int c = 0; c < 3; c++) {\r\n            if (grid[boxRow + r][boxCol + c] == num) return 0;\r\n        }\r\n    }\r\n    return 1;\r\n}\r\n\r\n// 回溯求解数独\r\nint solveSudoku(int grid[N][N]) {\r\n    for (int row = 0; row < N; row++) {\r\n        for (int col = 0; col < N; col++) {\r\n            if (grid[row][col] == 0) {  // 找到空格\r\n                for (int num = 1; num <= 9; num++) {\r\n                    if (isValid(grid, row, col, num)) {\r\n                        grid[row][col] = num;\r\n                        if (solveSudoku(grid)) return 1;\r\n                        grid[row][col] = 0;  // 回溯\r\n                    }\r\n                }\r\n                return 0;  // 无解\r\n            }\r\n        }\r\n    }\r\n    return 1;  // 全部填满\r\n}\r\n\r\nint main() {\r\n    int grid[N][N];\r\n    \r\n    // 读取输入\r\n    for (int i = 0; i < N; i++) {\r\n        for (int j = 0; j < N; j++) {\r\n            scanf(\"%d\", &grid[i][j]);\r\n        }\r\n    }\r\n    \r\n    // 求解\r\n    solveSudoku(grid);\r\n    \r\n    // 输出结果\r\n    for (int i = 0; i < N; i++) {\r\n        for (int j = 0; j < N; j++) {\r\n            printf(\"%d\", grid[i][j]);\r\n            if (j < N - 1) printf(\" \");\r\n        }\r\n        printf(\"\\n\");\r\n    }\r\n    \r\n    return 0;\r\n}','cpp','ACCEPTED',100,323,1000,NULL,NULL,'2026-05-27 16:07:11','2026-05-28 00:07:11','2026-05-28 00:07:11','2026-05-28 00:07:13','JudgeCluster-A',0,1640,12),(372,108,1,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nstruct Node {\r\n    int val;\r\n    Node* left;\r\n    Node* right;\r\n};\r\n\r\n// 故意创建超大数据结构：每个节点包含巨大数组\r\nstruct FatNode {\r\n    int val;\r\n    FatNode* left;\r\n    FatNode* right;\r\n    char garbage[100000]; // 每个节点浪费约100KB\r\n};\r\n\r\nFatNode* buildTree(int n) {\r\n    if (n == 0) return nullptr;\r\n    FatNode* node = new FatNode();\r\n    node->val = 0;\r\n    node->left = buildTree(n-1);  // 完全不平衡的递归\r\n    node->right = buildTree(n-1); // 指数级增长节点数\r\n    return node;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    int n;\r\n    cin >> n;\r\n    \r\n    vector<int> pre(n), in(n);\r\n    for (int i = 0; i < n; ++i) cin >> pre[i];\r\n    for (int i = 0; i < n; ++i) cin >> in[i];\r\n    \r\n    // 故意创建超内存：递归构建一棵巨大的树\r\n    FatNode* root = buildTree(n * 1000); // 疯狂放大规模\r\n    \r\n    // 假装在做后序遍历\r\n    cout << \"1\";\r\n    for (int i = 2; i <= n; ++i) cout << \" \" << i;\r\n    cout << endl;\r\n    \r\n    return 0;\r\n}','cpp','MEMORY_LIMIT_EXCEEDED',0,196,262144,'run: line 1:     3 Killed                  LD_LIBRARY_PATH=/usr/local/gcc-9.2.0/lib64 ./a.out\n',NULL,'2026-05-27 16:08:49','2026-05-28 00:08:49','2026-05-28 00:08:49','2026-05-28 00:09:00','JudgeCluster-A',171,10710,12),(373,108,1,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nstruct Node {\r\n    int val;\r\n    Node* left;\r\n    Node* right;\r\n};\r\n\r\n// 故意创建超大数据结构：每个节点包含巨大数组\r\nstruct FatNode {\r\n  